import { API_BASE } from '@/lib/api';
import axios from 'axios';

let refreshInFlight: Promise<string | null> | null = null;

function isJwtExpiredOrExpiring(token: string | null): boolean {
  if (!token) return true;
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return true;
    const payload = JSON.parse(atob(parts[1]));
    const exp = payload?.exp;
    if (!exp) return false;
    const nowSec = Math.floor(Date.now() / 1000);
    // Expired or less than 15 minutes remaining
    return (exp - nowSec) < 900;
  } catch {
    return false;
  }
}

/**
 * PHASE_4C967 — Restore access token when user profile exists but JWT was lost or expired.
 * Uses httpOnly refresh cookie and localStorage fallback for seamless cross-domain refresh.
 */
export async function ensureAccessToken(): Promise<string | null> {
  if (typeof window === 'undefined') return null;

  try {
    const existing = localStorage.getItem('accessToken');
    if (existing && !isJwtExpiredOrExpiring(existing)) return existing;

    const userRaw = localStorage.getItem('user');
    if (!userRaw || userRaw === 'undefined' || userRaw === 'null') return null;

    if (!refreshInFlight) {
      let storedRefreshToken: string | null = null;
      try {
        storedRefreshToken = localStorage.getItem('refreshToken');
      } catch { }

      refreshInFlight = axios
        .post(
          `${API_BASE}/auth/refresh`,
          storedRefreshToken ? { refreshToken: storedRefreshToken } : {},
          {
            withCredentials: true,
            headers: storedRefreshToken ? { Authorization: `Bearer ${storedRefreshToken}` } : {}
          }
        )
        .then((res) => {
          const token = res.data?.accessToken;
          if (token) {
            try {
              localStorage.setItem('accessToken', token);
              if (res.data.refreshToken) {
                localStorage.setItem('refreshToken', res.data.refreshToken);
              }
            } catch { }
            return token as string;
          }
          return null;
        })
        .catch((err) => {
          if (err?.response?.status === 401) {
            try {
              localStorage.removeItem('accessToken');
              localStorage.removeItem('refreshToken');
            } catch { }
          }
          return null;
        })
        .finally(() => {
          refreshInFlight = null;
        });
    }

    return refreshInFlight;
  } catch {
    return null;
  }
}