import { initializeApp, getApps, getApp } from 'firebase/app';
import { getMessaging, Messaging } from 'firebase/messaging';

// Public Web SDK Config (Mocks loaded by default if not set in environment)
export const firebaseConfig = {
  apiKey: process.env.NEXT_PUBLIC_FIREBASE_API_KEY || 'MOCK_API_KEY_1234567890',
  authDomain: process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN || 'mock-app.firebaseapp.com',
  projectId: process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID || 'mock-app',
  storageBucket: process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET || 'mock-app.appspot.com',
  messagingSenderId: process.env.NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID || '1234567890',
  appId: process.env.NEXT_PUBLIC_FIREBASE_APP_ID || '1:1234567890:web:abcdef123456'
};

export const vapidKey = process.env.NEXT_PUBLIC_FIREBASE_VAPID_KEY || 'MOCK_VAPID_KEY_ABC123';

// Helper to validate VAPID key encoding and length
export function isValidVapidKey(key: string | undefined): boolean {
  if (!key) return false;
  if (key === 'MOCK_VAPID_KEY_ABC123') return false;
  // A real VAPID public key is a base64url-encoded P-256 public key (typically 87 characters)
  if (key.length < 50) return false;
  try {
    const base64 = key.replace(/-/g, '+').replace(/_/g, '/');
    if (typeof window !== 'undefined') {
      window.atob(base64);
    } else {
      Buffer.from(base64, 'base64');
    }
    return true;
  } catch (e) {
    return false;
  }
}

const isMockFirebaseConfig = !process.env.NEXT_PUBLIC_FIREBASE_API_KEY || 
                             process.env.NEXT_PUBLIC_FIREBASE_API_KEY === 'MOCK_API_KEY_1234567890';

let app: ReturnType<typeof initializeApp> | undefined;
let messaging: Messaging | null = null;

if (typeof window !== 'undefined') {
  try {
    app = getApps().length === 0 ? initializeApp(firebaseConfig) : getApp();
    
    // Only initialize FCM if we have a valid VAPID key
      if (isValidVapidKey(vapidKey)) {
        // Guard browser compatibility for push messaging (safari/chrome/firefox checks)
        if ('serviceWorker' in navigator && 'PushManager' in window) {
          messaging = getMessaging(app);
        } else {
          console.warn('[FIREBASE] Push messaging is not supported in this browser environment.');
        }
      } else {
        console.warn('[FIREBASE] FCM is disabled: Missing or invalid VAPID key.');
      }
  } catch (error) {
    console.error('[FIREBASE] Failed to initialize Firebase SDK:', error);
  }
}

export { app, messaging };

export function getFirebaseClientDiagnostics() {
  return {
    hasApiKey: Boolean(process.env.NEXT_PUBLIC_FIREBASE_API_KEY && process.env.NEXT_PUBLIC_FIREBASE_API_KEY !== 'MOCK_API_KEY_1234567890'),
    hasVapidKey: isValidVapidKey(vapidKey),
    isMessagingInitialized: messaging !== null,
    isBrowserSupported: typeof window !== 'undefined' && 'serviceWorker' in navigator && 'PushManager' in window
  };
}


