import type { Metadata, Viewport } from "next";
import localFont from "next/font/local";
import "./globals.css";
import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";
import { GlobalErrorBoundary } from "@/components/GlobalErrorBoundary";
import { PHProvider } from "@/lib/analytics";
import { AxiosInterceptor } from "@/components/AxiosInterceptor";
import { SessionBootstrap } from "@/components/SessionBootstrap";
import InstallPrompt from "@/components/InstallPrompt";
import ServiceWorkerRegistrar from "@/components/ServiceWorkerRegistrar";
import BottomNav from "@/components/BottomNav";
import { LanguageProvider } from "@/components/LanguageContext";
import Script from "next/script";
import Link from "next/link";
import { MessageSquarePlus } from "lucide-react";
import BetaWidgets from "@/components/BetaWidgets";
import { ToastProvider } from "@/components/ui/ToastContext";
import OnboardingOverlay from "@/components/OnboardingOverlay";
import IndependenceCampaignModal from "@/components/IndependenceCampaignModal";
import AppUrlListener from "@/components/AppUrlListener";
import PlayStoreReviewPrompt from "@/components/PlayStoreReviewPrompt";
import IrctcServiceAdvisoryBanner from "@/components/IrctcServiceAdvisoryBanner";


const geistSans = localFont({
  src: "./fonts/GeistVF.woff",
  variable: "--font-geist-sans",
  weight: "100 900",
});
const geistMono = localFont({
  src: "./fonts/GeistMonoVF.woff",
  variable: "--font-geist-mono",
  weight: "100 900",
});

// UI-06 / Phase 146Q.1.15: Self-hosted local variable fonts (100% deterministic cold builds)
// next/font/local automatically applies font-display:swap and self-hosts WOFF2 assets
const notoSans = localFont({
  src: "./fonts/NotoSans-VariableFont_wdth,wght.woff2",
  variable: "--font-noto-sans",
  weight: "100 900",
  display: "swap",
});
const notoSansDevanagari = localFont({
  src: "./fonts/NotoSansDevanagari-VariableFont_wdth,wght.woff2",
  variable: "--font-noto-devanagari",
  weight: "100 900",
  display: "swap",
});
const notoSansGujarati = localFont({
  src: "./fonts/NotoSansGujarati-VariableFont_wdth,wght.woff2",
  variable: "--font-noto-gujarati",
  weight: "100 900",
  display: "swap",
});
const notoSansBengali = localFont({
  src: "./fonts/NotoSansBengali-VariableFont_wdth,wght.woff2",
  variable: "--font-noto-bengali",
  weight: "100 900",
  display: "swap",
});
const notoSansTamil = localFont({
  src: "./fonts/NotoSansTamil-VariableFont_wdth,wght.woff2",
  variable: "--font-noto-tamil",
  weight: "100 900",
  display: "swap",
});
const notoSansTelugu = localFont({
  src: "./fonts/NotoSansTelugu-VariableFont_wdth,wght.woff2",
  variable: "--font-noto-telugu",
  weight: "100 900",
  display: "swap",
});
const notoSansKannada = localFont({
  src: "./fonts/NotoSansKannada-VariableFont_wdth,wght.woff2",
  variable: "--font-noto-kannada",
  weight: "100 900",
  display: "swap",
});
const notoSansOriya = localFont({
  src: "./fonts/NotoSansOriya-VariableFont_wdth,wght.woff2",
  variable: "--font-noto-oriya",
  weight: "100 900",
  display: "swap",
});
const outfit = localFont({
  src: "./fonts/Outfit-VariableFont_wght.woff2",
  variable: "--font-outfit",
  weight: "100 900",
  display: "swap",
});

export const metadata: Metadata = {
  metadataBase: new URL("https://www.trayago.in"),
  alternates: { canonical: "/" },
  title: "Trayago | Intelligent Pan-India Travel Planner",
  description: "Find the fastest, smartest split journey train routes across India. Discover hidden connections, live availability, and AI-powered recommendations.",
  keywords: "Indian railways, IRCTC, train tickets, split journey, train routes, live train status, PNR status",
  manifest: "/manifest.json?v=3",
  icons: {
    icon: [
      { url: "/favicon.svg?v=2", type: "image/svg+xml" },
      { url: "/icon-192.png?v=2", sizes: "192x192", type: "image/png" },
      { url: "/icon-512.png?v=2", sizes: "512x512", type: "image/png" },
    ],
    apple: [
      { url: "/icons/apple-touch-icon.png?v=2", sizes: "180x180", type: "image/png" },
      { url: "/icon-192.png?v=2", sizes: "192x192", type: "image/png" },
    ],
  },
  appleWebApp: {
    capable: true,
    statusBarStyle: "black-translucent",
    title: "Trayago",
  },
  openGraph: {
    type: "website",
    locale: "en_IN",
    url: "https://www.trayago.in/",
    title: "Trayago - Smart Train Travel",
    description: "Never miss a train again. Discover hidden AI-powered split journeys when direct trains are full.",
    siteName: "Trayago",
    images: [{ url: "/og-image.png", width: 1200, height: 630, alt: "Trayago Preview" }],
  },
  twitter: {
    card: "summary_large_image",
    title: "Trayago - Smart Train Travel",
    description: "Discover hidden AI-powered split journeys when direct trains are full.",
    images: ["/og-image.png"],
    site: "@trayago",
    creator: "@trayago",
  },
  verification: {
    ...(process.env.NEXT_PUBLIC_GOOGLE_SITE_VERIFICATION && {
      google: process.env.NEXT_PUBLIC_GOOGLE_SITE_VERIFICATION,
    }),
    ...(process.env.NEXT_PUBLIC_BING_SITE_VERIFICATION && {
      other: {
        "msvalidate.01": process.env.NEXT_PUBLIC_BING_SITE_VERIFICATION,
      },
    }),
  },
};

export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
  maximumScale: 5,
  themeColor: "#0a0a0f",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  const adsenseClientId = process.env.NEXT_PUBLIC_ADSENSE_CLIENT_ID?.trim();
  const isValidAdsenseClient = Boolean(adsenseClientId && /^ca-pub-\d{10,20}$/i.test(adsenseClientId));

  return (
    <html lang="en">
      <head>
        {adsenseClientId && (
          isValidAdsenseClient ? (
            <Script
              id="google-adsense"
              src={`https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=${adsenseClientId}`}
              strategy="afterInteractive"
              crossOrigin="anonymous"
            />
          ) : null
        )}
        <script
          id="theme-init"
          dangerouslySetInnerHTML={{
            __html: `
              (function() {
                try {
                  var saved = localStorage.getItem('theme');
                  if (saved === 'dark' || (!saved && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
                    document.documentElement.classList.add('dark');
                  } else {
                    document.documentElement.classList.remove('dark');
                  }
                  if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') {
                    if (!sessionStorage.getItem('dev_sw_purged')) {
                      sessionStorage.setItem('dev_sw_purged', '1');
                      if ('serviceWorker' in navigator) {
                        navigator.serviceWorker.getRegistrations().then(function(regs) {
                          for (var i = 0; i < regs.length; i++) regs[i].unregister();
                        });
                      }
                      if ('caches' in window) {
                        caches.keys().then(function(keys) {
                          for (var j = 0; j < keys.length; j++) {
                            if (/workbox|trayago|next/i.test(keys[j])) {
                              caches.delete(keys[j]);
                            }
                          }
                        });
                      }
                    }
                  } } catch (e) {}
              })()
            `,
          }}
        />
        <script
          id="pwa-install-capture"
          dangerouslySetInnerHTML={{
            __html: `
              window.addEventListener('beforeinstallprompt', (e) => {
                e.preventDefault();
                window.deferredPrompt = e;
              });
            `,
          }}
        />
        <Script src="https://cdn.onesignal.com/sdks/web/v16/OneSignalSDK.page.js" strategy="afterInteractive" />
        <Script
          id="onesignal-init"
          strategy="afterInteractive"
          dangerouslySetInnerHTML={{
            __html: `
              window.OneSignalDeferred = window.OneSignalDeferred || [];
              const appId = "${process.env.NEXT_PUBLIC_ONESIGNAL_APP_ID || ''}";
              if (appId) {
                OneSignalDeferred.push(function(OneSignal) {
                  OneSignal.init({
                    appId: appId,
                    safari_web_id: "${process.env.NEXT_PUBLIC_ONESIGNAL_SAFARI_WEB_ID || ''}",
                    serviceWorkerPath: 'notification-sw.js',
                    serviceWorkerParam: {
                      scope: '/notification-scope/'
                    },
                    notifyButton: { 
                      enable: true,
                      offset: {
                        bottom: "80px",
                        right: "16px"
                      }
                    },
                  });
                });
              }
            `,
          }}
        />
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{
            __html: JSON.stringify({
              "@context": "https://schema.org",
              "@type": "WebApplication",
              "name": "Trayago",
              "url": "https://www.trayago.in",
              "description": "Intelligent Pan-India travel planner with AI-powered split journeys, confirmation predictions, and GPS live train tracking.",
              "applicationCategory": "TravelApplication",
              "operatingSystem": "All",
              "browserRequirements": "Requires HTML5, CSS3, and JavaScript.",
              "creator": {
                "@type": "Organization",
                "name": "Trayago",
                "url": "https://www.trayago.in"
              },
              "offers": {
                "@type": "Offer",
                "price": "0",
                "priceCurrency": "INR",
                "description": "Free core tracking features, with premium AI-powered route planning subscriptions available.",
                "category": "Free"
              }
            })
          }}
        />
      </head>
      <body suppressHydrationWarning className={`${geistSans.variable} ${geistMono.variable} ${notoSans.variable} ${notoSansDevanagari.variable} ${notoSansGujarati.variable} ${notoSansBengali.variable} ${notoSansTamil.variable} ${notoSansTelugu.variable} ${notoSansKannada.variable} ${notoSansOriya.variable} ${outfit.variable} antialiased bg-app text-main min-h-screen min-h-dvh flex flex-col pt-[env(safe-area-inset-top)]`}>
        <GlobalErrorBoundary>
          <LanguageProvider>
            <ToastProvider>
              <PHProvider>
                <ServiceWorkerRegistrar />
                <InstallPrompt />
                <BottomNav />
                <SessionBootstrap />
                <AxiosInterceptor />
                {/* Sticky Navbar */}
                <Navbar />

                {/* IRCTC IST Service Advisory Banner */}
                <IrctcServiceAdvisoryBanner />

                <main className="flex-1 w-full max-w-full min-w-0 overflow-x-hidden pb-[calc(5.5rem+env(safe-area-inset-bottom,0px))] md:pb-0">
                  {children}
                </main>

                {/* Responsive Footer */}
                <Footer />

                {/* Floating Feedback Button — desktop only to prevent mobile card and close-button collisions */}
                <Link
                  href="/feedback"
                  className="hidden md:flex fixed bottom-6 right-6 z-30 bg-rose-500 hover:bg-rose-400 text-white px-4 py-3 rounded-full shadow-lg shadow-rose-500/25 transition-all items-center gap-2 group active:scale-95 touch-manipulation focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-rose-500"
                  title="Report Bug / Feedback"
                >
                  <MessageSquarePlus className="w-5 h-5" />
                  <span className="font-semibold text-xs md:text-sm">Feedback</span>
                </Link>

                {/* Beta tester helper widgets */}
                <BetaWidgets />
                
                {/* Safe Client-side Onboarding */}
                <OnboardingOverlay />

                {/* 15 August Independence Day Campaign Modal (All users) */}
                <IndependenceCampaignModal />

                {/* Native App Deep Link Listener */}
                <AppUrlListener />

                {/* Google Play Store Review & Free Pro Reward Prompt */}
                <PlayStoreReviewPrompt />
              </PHProvider>
            </ToastProvider>
          </LanguageProvider>
        </GlobalErrorBoundary>
      </body>
    </html>
  );
}
