/**
 * Initialize PostHog once on the client side.
 * Only initializes in production with a valid key.
 * Never tracks PII, API secrets or raw payloads.
 */
export function PHProvider({ children }: { children: React.ReactNode }) {
  useEffect(() => {
    const key = process.env.NEXT_PUBLIC_POSTHOG_KEY;
    const host = process.env.NEXT_PUBLIC_POSTHOG_HOST || 'https://app.posthog.com';

    if (!key || process.env.NODE_ENV !== 'production') return;

    posthog.init(key, {
      api_host: host,
      // Do not autocapture sensitive inputs or forms
      autocapture: false,
      // Do not persist personal identifiers
      persistence: 'memory',
      // Disable session recording — no screen/payload capture
      disable_session_recording: true,
      // Send page views manually for SPA correctness
      capture_pageview: false,
    });
  }, []);

  return <PostHogProvider client={posthog}>{children}</PostHogProvider>;
}

