'use client';

import { useEffect, useCallback } from 'react';
import { Capacitor } from '@capacitor/core';

export function useCapacitor() {
  const isNative = Capacitor.isNativePlatform();
  const platform = Capacitor.getPlatform();

  // 1. Safe Native Haptic Feedback Scaffolding
  const triggerHaptic = useCallback((type: 'light' | 'medium' | 'heavy' | 'success' | 'warning' | 'error' = 'light') => {
    try {
      if (typeof window === 'undefined') return;

      if (isNative) {
        console.log(`[Capacitor] Triggering native haptic feedback: ${type}`);
        // If the native haptics plugin is installed in the future, Capacitor can call it dynamically.
        // For now, we fall back to the standard web vibration API.
      }

      // Web Vibrate API fallback (supported on Chrome/Android)
      if ('vibrate' in navigator) {
        const patterns = {
          light: [15],
          medium: [30],
          heavy: [60],
          success: [30, 50, 30],
          warning: [40, 60, 40],
          error: [60, 100, 60],
        };
        navigator.vibrate(patterns[type] || [15]);
      }
    } catch (err) {
      console.warn('[Capacitor] Vibrate/Haptic feedback failed:', err);
    }
  }, [isNative]);

  // 2. Safe Native Share Sheet Scaffolding
  const nativeShare = useCallback(async (title: string, text: string, url: string) => {
    try {
      if (typeof window === 'undefined') return false;

      // Use standard Web Share API which works in Capacitor WebView and mobile browsers
      if (navigator.share) {
        console.log('[Capacitor/Web] Triggering native share sheet...');
        await navigator.share({ title, text, url });
        return true;
      } else {
        console.warn('[Capacitor/Web] Web Share API not supported on this platform.');
        return false;
      }
    } catch (err: any) {
      // AbortError is thrown when user cancels the share dialog, which is normal behavior
      if (err.name !== 'AbortError') {
        console.error('[Capacitor/Web] Share sheet failed:', err);
      }
      return false;
    }
  }, []);

  // 3. Native Status Bar Styling Sync
  const syncStatusBarColor = useCallback((themeMode: 'light' | 'dark') => {
    try {
      if (typeof document === 'undefined') return;

      const metaThemeColor = document.querySelector('meta[name="theme-color"]');
      const targetColor = themeMode === 'dark' ? '#0a0a0f' : '#2563EB';

      if (metaThemeColor) {
        metaThemeColor.setAttribute('content', targetColor);
      }

      if (isNative) {
        console.log(`[Capacitor] Syncing native status bar theme color: ${targetColor}`);
      }
    } catch (err) {
      console.warn('[Capacitor] Status bar sync failed:', err);
    }
  }, [isNative]);

  // Sync theme-color meta tag on initialization
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const isDark = document.documentElement.classList.contains('dark');
    syncStatusBarColor(isDark ? 'dark' : 'light');
  }, [syncStatusBarColor]);

  return {
    isNative,
    platform,
    triggerHaptic,
    nativeShare,
    syncStatusBarColor,
  };
}
