'use client';

import React, { createContext, useCallback, useContext, useEffect, useState } from 'react';
import { Language, TranslationKey, loadLanguagePack, enStatic } from '../lib/translations';

interface LanguageContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
  t: (key: TranslationKey, params?: Record<string, string | number>) => string;
  isHindi: boolean;
  loading: boolean;
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguageState] = useState<Language>('en');
  const [activePack, setActivePack] = useState<Record<string, string>>(enStatic);
  const [loading, setLoading] = useState(true);

  // Load language pack dynamically when language selection changes
  useEffect(() => {
    let active = true;
    setLoading(true);
    
    loadLanguagePack(language).then((pack) => {
      if (active) {
        setActivePack(pack);
        setLoading(false);

        // Update <html lang="..."> for accessibility + SEO
        document.documentElement.lang = language;

        // Swap lang-* class for Indic font override (see globals.css)
        const htmlEl = document.documentElement;
        ['hi', 'mr', 'gu', 'bn', 'ta', 'te', 'kn', 'or'].forEach(l => htmlEl.classList.remove(`lang-${l}`));
        if (language !== 'en') {
          htmlEl.classList.add(`lang-${language}`);
        }
      }
    });

    return () => {
      active = false;
    };
  }, [language]);

  // Load locale selection on mount (Auto-detection & Persistence)
  useEffect(() => {
    try {
      const savedLang = (localStorage.getItem('trayago_voice_lang') || localStorage.getItem('trayago_lang')) as Language;
      const allLangs: Language[] = ['en', 'hi', 'mr', 'gu', 'bn', 'ta', 'te', 'kn', 'or'];
      
      if (savedLang && allLangs.includes(savedLang)) {
        setLanguageState(savedLang);
      } else if (typeof navigator !== 'undefined') {
        // Auto-detect browser/device locale
        const systemLocales = navigator.languages || [navigator.language];
        let detected: Language = 'en';

        const localeMap: Record<string, Language> = {
          'hi': 'hi', 'mr': 'mr', 'gu': 'gu',
          'bn': 'bn', 'ta': 'ta', 'te': 'te',
          'kn': 'kn', 'or': 'or', 'od': 'or',
          'en': 'en'
        };

        for (const loc of systemLocales) {
          const prefix = loc.toLowerCase().split('-')[0];
          if (localeMap[prefix]) {
            detected = localeMap[prefix];
            break;
          }
        }
        
        setLanguageState(detected);
      }
    } catch (err) {
      console.warn('Failed to detect system or storage locale settings:', err);
    }
  }, []);

  // Synchronize across components when voiceService or alarm sets language
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const handleSync = (e: any) => {
      const newL = e.detail?.lang;
      const allLangs: Language[] = ['en', 'hi', 'mr', 'gu', 'bn', 'ta', 'te', 'kn', 'or'];
      if (newL && allLangs.includes(newL)) {
        setLanguageState((prev) => (prev !== newL ? newL : prev));
      }
    };
    window.addEventListener('trayago:language-change', handleSync);
    return () => window.removeEventListener('trayago:language-change', handleSync);
  }, []);

  // Prefetch non-active translation packs in the background when online and idle
  // to avoid ChunkLoadError when the user switches languages in offline mode.
  useEffect(() => {
    if (typeof window === 'undefined') return;
    
    // Check connection status
    if (typeof navigator !== 'undefined' && !navigator.onLine) return;

    const prefetchOtherLanguages = async () => {
      const allLangs: Language[] = ['en', 'hi', 'mr', 'gu', 'bn', 'ta', 'te', 'kn', 'or'];
      for (const lang of allLangs) {
        if (lang !== language) {
          try {
            await loadLanguagePack(lang);
          } catch (e) {
            console.warn(`[LanguageContext] Failed to prefetch locale: ${lang}`, e);
          }
        }
      }
    };

    // Run when browser is idle to avoid impact on initial load performance
    const delayTimer = setTimeout(() => {
      if (typeof window.requestIdleCallback === 'function') {
        window.requestIdleCallback(() => prefetchOtherLanguages());
      } else {
        prefetchOtherLanguages();
      }
    }, 5000);

    return () => clearTimeout(delayTimer);
  }, [language]);

  const setLanguage = useCallback((lang: Language) => {
    try {
      setLanguageState(lang);
      localStorage.setItem('trayago_lang', lang);
      localStorage.setItem('trayago_voice_lang', lang);
      if (typeof window !== 'undefined') {
        window.dispatchEvent(new CustomEvent('trayago:language-change', { detail: { lang } }));
      }
    } catch (err) {
      console.warn('Failed to save language override:', err);
    }
  }, []);

  const t = useCallback((key: TranslationKey, params?: Record<string, string | number>): string => {
    let text = activePack[key] || enStatic[key] || key;

    if (params) {
      Object.entries(params).forEach(([placeholder, value]) => {
        text = text.replace(new RegExp(`{${placeholder}}`, 'g'), String(value));
      });
    }

    return text;
  }, [activePack]);

  const value: LanguageContextType = {
    language,
    setLanguage,
    t,
    isHindi: language === 'hi',
    loading,
  };

  return (
    <LanguageContext.Provider value={value}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (context === undefined) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
}