"use client";

import Link from "next/link";
import { AlertTriangle, RefreshCw } from "lucide-react";

// Verified-existing routes only — mirrors the list in not-found.tsx.
const DESTINATIONS: { href: string; label: string }[] = [
  { href: "/", label: "Train Search" },
  { href: "/live", label: "Live Train Status" },
  { href: "/pnr", label: "PNR Status" },
  { href: "/tracker", label: "Train Tracker" },
  { href: "/ai-waitlist-rescue", label: "AI Waitlist Rescue" },
  { href: "/news", label: "News & Guides" },
];

/**
 * Route-level error boundary.
 *
 * SECURITY: the `error` object is intentionally NOT rendered. Error messages and
 * stack traces can leak internal paths, API shapes, and upstream provider detail.
 * Diagnostics are handled by Sentry, which is already wired up globally.
 */
export default function Error({
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  return (
    <div className="min-h-screen bg-app text-main flex flex-col items-center justify-center p-6 relative overflow-hidden">
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(37,99,235,0.08)_0%,transparent_60%)] pointer-events-none" />

      <div className="w-full max-w-lg bg-card/60 backdrop-blur-xl border border-subtle rounded-3xl p-8 shadow-2xl relative z-10 flex flex-col items-center">
        <div className="w-20 h-20 bg-amber-500/10 rounded-full flex items-center justify-center border border-amber-500/20 mb-6">
          <AlertTriangle className="w-10 h-10 text-amber-500" />
        </div>

        <h1 className="text-2xl font-black tracking-tight mb-2 text-main text-center">
          Something went wrong
        </h1>

        <p className="text-secondary text-sm mb-6 leading-relaxed text-center">
          This page could not be loaded. It is usually temporary — trying again
          often resolves it.
        </p>

        <button
          type="button"
          onClick={() => reset()}
          className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-2xl transition-all shadow-md flex items-center justify-center gap-3 active:scale-[0.98] select-none touch-manipulation focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
        >
          <RefreshCw className="w-5 h-5" />
          Try again
        </button>

        <nav aria-label="Popular Trayago pages" className="w-full mt-8">
          <p className="text-muted text-[10px] uppercase font-black tracking-wider mb-3 text-center">
            Or go to
          </p>
          <ul className="w-full flex flex-wrap items-center justify-center gap-2">
            {DESTINATIONS.map((item) => (
              <li key={item.href}>
                <Link
                  href={item.href}
                  className="inline-flex items-center text-xs font-semibold px-3 py-1.5 rounded-xl bg-input/50 hover:bg-input border border-subtle text-secondary hover:text-primary transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
                >
                  {item.label}
                </Link>
              </li>
            ))}
          </ul>
        </nav>
      </div>
    </div>
  );
}
