'use client';

import React, { useEffect, useState } from 'react';
import { Smartphone, Download, X, Share, TrainFront } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

interface EngagementMetrics {
  searches: number;
  pnrChecks: number;
  timeOnSite: number;
  firstVisit: number;
}

export default function InstallPrompt() {
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [showPrompt, setShowPrompt] = useState(false);
  const [showIOSPrompt, setShowIOSPrompt] = useState(false);
  const [hasLegacyApp, setHasLegacyApp] = useState(false);
  const [engagementMet, setEngagementMet] = useState(false);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    // Check if user previously dismissed the prompt
    try {
      const dismissedTime = localStorage.getItem('pwa_prompt_dismissed');
      if (dismissedTime) {
        const diff = Date.now() - parseInt(dismissedTime, 10);
        const sevenDays = 7 * 24 * 60 * 60 * 1000;
        
        // Lockout period of 24 hours once dismissed so it does not repeatedly pop up
        const lockoutPeriod = 24 * 60 * 60 * 1000;

        if (diff < lockoutPeriod) {
          console.log(`[PWA] Install prompt dismissed recently. Lockout active for ${lockoutPeriod / 1000}s.`);
          return;
        }
      }
    } catch (e) {
      console.warn('Storage blocked: unable to read dismiss state', e);
    }

    const isStandalone = 
      window.matchMedia('(display-mode: standalone)').matches || 
      (navigator as any).standalone === true;

    if (isStandalone) return;

    // Check engagement threshold before showing prompt
    const checkEngagement = (): boolean => {
      // Engagement threshold removed per user request - always show install prompt immediately
      return true;
    };

    const engagement = checkEngagement();
    setEngagementMet(engagement);

    if (!engagement) {
      console.log('[PWA] Engagement threshold not met. Prompt deferred.');
      
      // Track time on site
      const startTime = Date.now();
      const timeTracker = setInterval(() => {
        try {
          const metricsRaw = localStorage.getItem('pwa_engagement_metrics');
          if (metricsRaw) {
            const metrics: EngagementMetrics = JSON.parse(metricsRaw);
            metrics.timeOnSite = Date.now() - metrics.firstVisit;
            localStorage.setItem('pwa_engagement_metrics', JSON.stringify(metrics));
            
            // Check if threshold met via time
            if (metrics.timeOnSite >= 30000 && !engagementMet) {
              setEngagementMet(true);
              console.log('[PWA] Time threshold reached. Engagement met.');
            }
          }
        } catch (e) {
          console.warn('[PWA] Failed to update time metrics', e);
        }
      }, 5000); // Update every 5 seconds

      return () => clearInterval(timeTracker);
    }

    // Check if event was already captured globally (only if engagement met)
    if ((window as any).deferredPrompt && engagement) {
      setDeferredPrompt((window as any).deferredPrompt);
      setShowPrompt(true);
      console.log('[PWA] Restored pre-captured install prompt.');
    }

    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e);
      
      // Only show prompt if engagement threshold met
      if (engagement) {
        setShowPrompt(true);
        console.log('[PWA] Native install prompt caught and shown (engagement met).');
      } else {
        console.log('[PWA] Native install prompt caught but deferred (engagement not met).');
      }
      
      (window as any).deferredPrompt = e; // Sync globally
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);

    // Detect legacy or conflicting installations
    if ('getInstalledRelatedApps' in navigator) {
      (navigator as any).getInstalledRelatedApps().then((relatedApps: any[]) => {
        const legacy = relatedApps.find((app) => 
          app.platform === 'webapp' || 
          app.id === 'com.trayago' ||
          app.url?.includes('trayago')
        );
        if (legacy) {
          console.warn('[PWA] Legacy or conflicting installed app detected. Uninstall existing app to allow re-installation.');
          setHasLegacyApp(true);
        }
      }).catch((err: any) => {
        console.warn('Failed to fetch installed related apps:', err);
      });
    }

    const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);
    if (isIOS && !isStandalone && engagement) {
      const timer = setTimeout(() => {
        setShowIOSPrompt(true);
      }, 3000);
      return () => clearTimeout(timer);
    }

    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    };
  }, [engagementMet]);

  // Listen for engagement events from other components
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const handleEngagementEvent = (event: CustomEvent) => {
      try {
        const { type } = event.detail;
        const metricsRaw = localStorage.getItem('pwa_engagement_metrics');
        
        if (metricsRaw) {
          const metrics: EngagementMetrics = JSON.parse(metricsRaw);
          
          if (type === 'search') {
            metrics.searches += 1;
            console.log('[PWA] Search tracked. Total:', metrics.searches);
          } else if (type === 'pnr') {
            metrics.pnrChecks += 1;
            console.log('[PWA] PNR check tracked. Total:', metrics.pnrChecks);
          }
          
          localStorage.setItem('pwa_engagement_metrics', JSON.stringify(metrics));
          
          // Check if threshold now met
          if ((metrics.searches >= 1 || metrics.pnrChecks >= 1) && !engagementMet) {
            setEngagementMet(true);
            console.log('[PWA] Engagement threshold met via user action.');
            
            // Trigger prompt if deferred event exists
            if ((window as any).deferredPrompt) {
              setDeferredPrompt((window as any).deferredPrompt);
              setShowPrompt(true);
            } else if (/iPad|iPhone|iPod/.test(navigator.userAgent)) {
              setShowIOSPrompt(true);
            }
          }
        }
      } catch (e) {
        console.warn('[PWA] Failed to handle engagement event', e);
      }
    };

    window.addEventListener('pwa:engagement', handleEngagementEvent as EventListener);
    
    return () => {
      window.removeEventListener('pwa:engagement', handleEngagementEvent as EventListener);
    };
  }, [engagementMet]);

  const handleInstall = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    console.log(`PWA install prompt choice: ${outcome}`);
    setDeferredPrompt(null);
    setShowPrompt(false);
  };

  const handleDismiss = () => {
    try {
      localStorage.setItem('pwa_prompt_dismissed', Date.now().toString());
    } catch (e) {}
    setShowPrompt(false);
    setShowIOSPrompt(false);
  };

  if (!showPrompt && !showIOSPrompt) return null;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0, y: 50, scale: 0.95 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        exit={{ opacity: 0, y: 20, scale: 0.95 }}
        transition={{ type: 'spring', stiffness: 350, damping: 25 }}
        className="fixed bottom-[calc(4.5rem+env(safe-area-inset-bottom))] md:bottom-6 left-4 right-4 md:left-auto md:right-6 md:w-96 z-50 select-none"
      >
        <div className="bg-card/85 backdrop-blur-2xl border border-strong rounded-3xl p-5 shadow-[0_10px_40px_rgba(0,0,0,0.15)] dark:shadow-[0_10px_40px_rgba(0,0,0,0.4)] flex flex-col gap-4 text-main relative overflow-hidden">
          {/* Subtle ambient background glow */}
          <div className="absolute top-0 right-0 w-24 h-24 bg-blue-500/5 rounded-full blur-xl pointer-events-none" />

          {/* Banner Header */}
          <div className="flex items-start justify-between relative z-10">
            <div className="flex items-center gap-3">
              <div className="w-11 h-11 bg-gradient-to-br from-blue-500 via-blue-600 to-indigo-700 rounded-2xl flex items-center justify-center shrink-0 shadow-md shadow-blue-500/25 border border-white/20">
                <TrainFront className="w-6 h-6 text-white" />
              </div>
              <div className="text-left">
                <h3 className="font-extrabold text-sm text-main leading-tight flex items-center gap-1.5">
                  Tray<span className="text-blue-500">ago</span>
                  <span className="text-[10px] font-black text-blue-500 bg-blue-500/10 px-1.5 py-0.5 rounded-full border border-blue-500/20 uppercase">App</span>
                </h3>
                <p className="text-muted text-[11px] mt-0.5 leading-snug font-medium">Smart Railway Assistant • AI Split Journeys &amp; Live GPS</p>
              </div>
            </div>
            <button 
              onClick={handleDismiss} 
              className="text-muted hover:text-main p-1.5 rounded-xl hover:bg-input transition-colors shrink-0"
              title="Dismiss"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {/* Legacy App Notice */}
          {hasLegacyApp && (
            <div className="text-[10px] text-amber-500 bg-amber-500/10 border border-amber-500/20 rounded-2xl p-3 leading-normal relative z-10 text-left">
              <strong>Notice:</strong> A version of this app is already installed. If you don&#39;t see updates, please uninstall it first before reinstalling.
            </div>
          )}

          {/* Native Android/Chrome Install Actions */}
          {showPrompt && deferredPrompt && (
            <motion.button
              whileTap={{ scale: 0.98 }}
              onClick={handleInstall}
              className="relative z-10 w-full py-3 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white text-xs font-black uppercase tracking-wider rounded-2xl shadow-lg shadow-blue-600/15 flex items-center justify-center gap-2 transition-all cursor-pointer touch-manipulation"
            >
              <Download className="w-4 h-4" />
              Install App
            </motion.button>
          )}

          {/* iOS/Safari Manual Add Instruction */}
          {showIOSPrompt && (
            <div className="text-xs text-muted bg-input/40 border border-subtle rounded-2xl p-3 flex flex-col gap-2 relative z-10">
              <div className="flex items-center gap-2 text-secondary font-bold">
                <Share className="w-4 h-4 text-blue-500 shrink-0" />
                <span>How to Install on iOS:</span>
              </div>
              <ol className="list-decimal list-inside space-y-1.5 pl-1 leading-normal">
                <li>Tap the <span className="text-main font-black">Share</span> button in Safari.</li>
                <li>Scroll down and select <span className="text-main font-black">Add to Home Screen</span>.</li>
              </ol>
            </div>
          )}

        </div>
      </motion.div>
    </AnimatePresence>
  );
}
