/**
 * IST (Indian Standard Time, UTC+5:30) Time Utilities
 * PHASE_087N173 — Pure client-side IST calculation for IRCTC service advisories.
 *
 * Requirements:
 * - Pure IST calculation (no backend time ping).
 * - Zero external dependencies.
 * - Robust midnight crossover handling for PRS night maintenance (11:30 PM - 01:00 AM IST).
 * - Accurate Tatkal rush window detection (10:00 AM - 11:15 AM IST).
 */

export interface IstTimeComponents {
  hours: number;
  minutes: number;
  totalMinutes: number; // 0 to 1439
  formattedTime: string;
}

export type AdvisoryType = 'TATKAL' | 'NIGHT_MAINTENANCE' | null;

export interface IstAdvisoryStatus {
  isActive: boolean;
  type: AdvisoryType;
  title: string;
  message: string;
  windowLabel: string;
}

/**
 * Approved advisory copy (N172 approved wording - strictly advisory, never claims IRCTC is down)
 */
export const IRCTC_ADVISORY_MESSAGES = {
  TATKAL:
    "Suchna: IRCTC Tatkal & booking window ke dauran (9:30 AM – 11:20 AM IST) railway servers par heavy traffic rehta hai. Seat availability aur PNR check me thoda samay lag sakta hai.",
  NIGHT_MAINTENANCE:
    "Suchna: Daily Indian Railways PRS maintenance routine (11:30 PM – 01:00 AM IST) ke dauran upstream live updates thodi der ke liye prabhavit ho sakte hain."
} as const;

/**
 * Converts a given Date (or current time) to IST minutes from midnight (0 to 1439).
 * Uses UTC timestamp arithmetic to ensure absolute timezone independence.
 */
export function getIstCurrentMinutes(date: Date = new Date()): number {
  try {
    const formatter = new Intl.DateTimeFormat('en-US', {
      timeZone: 'Asia/Kolkata',
      hour: 'numeric',
      minute: 'numeric',
      hour12: false
    });
    const parts = formatter.formatToParts(date);
    const h = parseInt(parts.find(p => p.type === 'hour')?.value || '0', 10) % 24;
    const m = parseInt(parts.find(p => p.type === 'minute')?.value || '0', 10);
    return h * 60 + m;
  } catch {
    const utcMs = date.getTime() + date.getTimezoneOffset() * 60000;
    const istDate = new Date(utcMs + 5.5 * 3600000);
    return istDate.getHours() * 60 + istDate.getMinutes();
  }
}

/**
 * Returns hours and minutes in IST.
 */
export function getIstTime(date: Date = new Date()): IstTimeComponents {
  try {
    const formatter = new Intl.DateTimeFormat('en-US', {
      timeZone: 'Asia/Kolkata',
      hour: 'numeric',
      minute: 'numeric',
      hour12: false
    });
    const parts = formatter.formatToParts(date);
    const hours = parseInt(parts.find(p => p.type === 'hour')?.value || '0', 10) % 24;
    const minutes = parseInt(parts.find(p => p.type === 'minute')?.value || '0', 10);
    const totalMinutes = hours * 60 + minutes;
    const formattedTime = `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')} IST`;
    return { hours, minutes, totalMinutes, formattedTime };
  } catch {
    const utcMs = date.getTime() + date.getTimezoneOffset() * 60000;
    const istDate = new Date(utcMs + 5.5 * 3600000);
    const hours = istDate.getHours();
    const minutes = istDate.getMinutes();
    const totalMinutes = hours * 60 + minutes;
    const formattedTime = `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')} IST`;
    return { hours, minutes, totalMinutes, formattedTime };
  }
}

/**
 * Tatkal & Rush Window: 9:30 AM (570m) to 11:20 AM (680m) IST
 */
export function isTatkalWindow(totalMinutes?: number): boolean {
  const mins = totalMinutes !== undefined ? totalMinutes : getIstCurrentMinutes();
  return mins >= 570 && mins <= 680;
}

/**
 * Night Maintenance Window: 11:30 PM (1410m) to 01:00 AM (60m) IST
 * Handles midnight crossover seamlessly: mins >= 1410 OR mins <= 60.
 */
export function isNightMaintenanceWindow(totalMinutes?: number): boolean {
  const mins = totalMinutes !== undefined ? totalMinutes : getIstCurrentMinutes();
  return mins >= 1410 || mins <= 60;
}

/**
 * Evaluates current IST time and returns advisory status with advisory message.
 */
export function getIstAdvisoryStatus(date: Date = new Date()): IstAdvisoryStatus {
  const mins = getIstCurrentMinutes(date);

  if (isNightMaintenanceWindow(mins)) {
    return {
      isActive: true,
      type: 'NIGHT_MAINTENANCE',
      title: 'PRS Maintenance Window (11:30 PM – 01:00 AM IST)',
      message: IRCTC_ADVISORY_MESSAGES.NIGHT_MAINTENANCE,
      windowLabel: '11:30 PM – 01:00 AM IST'
    };
  }

  if (isTatkalWindow(mins)) {
    return {
      isActive: true,
      type: 'TATKAL',
      title: 'High Traffic Advisory (9:30 AM – 11:20 AM IST)',
      message: IRCTC_ADVISORY_MESSAGES.TATKAL,
      windowLabel: '9:30 AM – 11:20 AM IST'
    };
  }

  return {
    isActive: false,
    type: null,
    title: '',
    message: '',
    windowLabel: ''
  };
}
